import { promises as fs } from "fs";
import path from "path";
import crypto from "crypto";

const DATA_FILE = path.join(process.cwd(), "data", "books.json");

export async function getBooks() {
  try {
    const raw = await fs.readFile(DATA_FILE, "utf8");
    return JSON.parse(raw);
  } catch (err) {
    if (err.code === "ENOENT") return [];
    throw err;
  }
}

export async function getBook(id) {
  const books = await getBooks();
  return books.find((book) => book.id === id) ?? null;
}

async function saveBooks(books) {
  await fs.mkdir(path.dirname(DATA_FILE), { recursive: true });
  await fs.writeFile(DATA_FILE, JSON.stringify(books, null, 2) + "\n");
}

export async function createBook({ title, author, notes }) {
  const books = await getBooks();
  const book = {
    id: crypto.randomUUID(),
    title,
    author,
    notes,
    status: "reading",
    addedAt: new Date().toISOString(),
    finishedAt: null,
  };
  books.push(book);
  await saveBooks(books);
  return book;
}

export async function markFinished(id) {
  const books = await getBooks();
  const book = books.find((b) => b.id === id);
  if (!book) return null;
  book.status = "finished";
  book.finishedAt = new Date().toISOString();
  await saveBooks(books);
  return book;
}

