import Link from "next/link";
import { getBooks } from "../lib/books.js";
import { addBook, finishBook } from "./actions.js";

export const dynamic = "force-dynamic";

function BookList({ books, showFinishButton }) {
  if (books.length === 0) {
    return <p className="empty">Nothing here yet.</p>;
  }
  return (
    <ul className="book-list">
      {books.map((book) => (
        <li key={book.id} className="book-item">
          <div>
            <Link href={`/books/${book.id}`} className="book-title">
              {book.title}
            </Link>
            <span className="book-author"> by {book.author}</span>
          </div>
          {showFinishButton && (
            <form action={finishBook}>
              <input type="hidden" name="id" value={book.id} />
              <button type="submit" className="secondary">
                Mark as finished
              </button>
            </form>
          )}
        </li>
      ))}
    </ul>
  );
}

export default async function HomePage() {
  const books = await getBooks();
  const reading = books.filter((b) => b.status === "reading");
  const finished = books.filter((b) => b.status === "finished");

  return (
    <>
      <h1>My Books</h1>

      <section>
        <h2>Currently reading</h2>
        <BookList books={reading} showFinishButton />
      </section>

      <section>
        <h2>Finished</h2>
        <BookList books={finished} showFinishButton={false} />
      </section>

      <section>
        <h2>Add a book</h2>
        <form action={addBook} className="add-form">
          <label>
            Title
            <input type="text" name="title" required />
          </label>
          <label>
            Author
            <input type="text" name="author" required />
          </label>
          <label>
            Notes
            <textarea name="notes" rows={4} />
          </label>
          <button type="submit">Add book</button>
        </form>
      </section>
    </>
  );
}

