import Link from "next/link";
import { notFound } from "next/navigation";
import { getBook } from "../../../lib/books.js";
import { finishBook } from "../../actions.js";

export const dynamic = "force-dynamic";

export default async function BookPage({ params }) {
  const { id } = await params;
  const book = await getBook(id);
  if (!book) notFound();

  return (
    <>
      <p>
        <Link href="/">&larr; All books</Link>
      </p>

      <h1>{book.title}</h1>
      <p className="book-author">by {book.author}</p>
      <p>
        <span className={`badge ${book.status}`}>
          {book.status === "finished" ? "Finished" : "Currently reading"}
        </span>
      </p>

      {book.status === "reading" && (
        <form action={finishBook}>
          <input type="hidden" name="id" value={book.id} />
          <button type="submit" className="secondary">
            Mark as finished
          </button>
        </form>
      )}

      <section>
        <h2>Notes</h2>
        {book.notes ? (
          <p className="notes">{book.notes}</p>
        ) : (
          <p className="empty">No notes for this book.</p>
        )}
      </section>
    </>
  );
}

