* {
  box-sizing: border-box;
}

body {
  margin: 0;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto,
    Helvetica, Arial, sans-serif;
  color: #1a1a1a;
  background: #fafafa;
  line-height: 1.5;
}

main {
  max-width: 640px;
  margin: 0 auto;
  padding: 2rem 1rem 4rem;
}

h1 {
  margin: 0 0 1.5rem;
}

h2 {
  margin: 2rem 0 0.75rem;
  font-size: 1.1rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  color: #555;
}

a {
  color: #0b5fff;
}

.book-list {
  list-style: none;
  margin: 0;
  padding: 0;
}

.book-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding: 0.75rem 1rem;
  margin-bottom: 0.5rem;
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 8px;
}

.book-title {
  font-weight: 600;
}

.book-author {
  color: #666;
}

.empty {
  color: #888;
  font-style: italic;
}

.add-form {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
  padding: 1rem;
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 8px;
}

.add-form label {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
  font-weight: 600;
  font-size: 0.9rem;
}

.add-form input,
.add-form textarea {
  font: inherit;
  font-weight: 400;
  padding: 0.5rem;
  border: 1px solid #ccc;
  border-radius: 6px;
}

button {
  font: inherit;
  padding: 0.5rem 1rem;
  border: none;
  border-radius: 6px;
  background: #0b5fff;
  color: #fff;
  cursor: pointer;
  align-self: flex-start;
  white-space: nowrap;
}

button:hover {
  background: #0a4fd6;
}

button.secondary {
  background: #eef3ff;
  color: #0b5fff;
  border: 1px solid #c8d8ff;
}

button.secondary:hover {
  background: #dde8ff;
}

.badge {
  display: inline-block;
  padding: 0.15rem 0.6rem;
  border-radius: 999px;
  font-size: 0.85rem;
  font-weight: 600;
}

.badge.reading {
  background: #fff3cd;
  color: #7a5c00;
}

.badge.finished {
  background: #d7f5dd;
  color: #14652a;
}

.notes {
  white-space: pre-wrap;
  background: #fff;
  border: 1px solid #e2e2e2;
  border-radius: 8px;
  padding: 1rem;
}

